package com.wandertrace.storage;
import java.io.*;import java.nio.file.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Primary;import org.springframework.stereotype.Service;
@Service @Primary public class LocalMediaStorageService implements MediaStorageService {private final Path root;public LocalMediaStorageService(@Value("${wandertrace.storage.local-path:./data/media}")String root){this.root=Path.of(root).toAbsolutePath().normalize();}public StoredObject upload(String key,InputStream content,long size,String type)throws IOException{if(key.contains("..")||key.startsWith("/"))throw new IOException("Unsafe storage key");Path file=root.resolve(key).normalize();if(!file.startsWith(root))throw new IOException("Unsafe storage key");Files.createDirectories(file.getParent());Files.copy(content,file,StandardCopyOption.REPLACE_EXISTING);return new StoredObject(key,getUrl(key));}public void delete(String key)throws IOException{Files.deleteIfExists(root.resolve(key).normalize());}public boolean exists(String key){return Files.exists(root.resolve(key).normalize());}public String getUrl(String key){return "/api/media/content/"+key;}}
